import re
from decimal import Decimal, ROUND_HALF_UP

_UNIT_SECONDS = {}
for _names, _secs in [
    (("s", "sec", "secs", "second", "seconds"), 1),
    (("m", "min", "mins", "minute", "minutes"), 60),
    (("h", "hr", "hrs", "hour", "hours"), 3600),
    (("d", "day", "days"), 86400),
    (("w", "wk", "wks", "week", "weeks"), 604800),
]:
    for _n in _names:
        _UNIT_SECONDS[_n] = _secs

_NUM = r"\d+(?:\.\d+)?"
_COMPONENT_RE = re.compile(r"\s*(" + _NUM + r")\s*([A-Za-z]+)")
_FULL_COMPONENTS_RE = re.compile(r"(?:\s*" + _NUM + r"\s*[A-Za-z]+)+\s*")
_ISO_RE = re.compile(
    r"P(?:(" + _NUM + r")W)?(?:(" + _NUM + r")D)?"
    r"(?:T(?:(" + _NUM + r")H)?(?:(" + _NUM + r")M)?(?:(" + _NUM + r")S)?)?"
)
_BARE_INT_RE = re.compile(r"\d+")
_CLOCK_FIELD_RE = re.compile(r"\d+(?:\.\d+)?")


def _to_seconds(total: Decimal) -> int:
    return int(total.quantize(Decimal(1), rounding=ROUND_HALF_UP))


def _parse_iso(text: str) -> int:
    m = _ISO_RE.fullmatch(text)
    if not m:
        raise ValueError(f"invalid ISO 8601 duration: {text!r}")
    weeks, days, hours, minutes, seconds = m.groups()
    if all(g is None for g in m.groups()):
        raise ValueError(f"empty ISO 8601 duration: {text!r}")
    if text.endswith("T"):
        raise ValueError(f"invalid ISO 8601 duration: {text!r}")
    total = Decimal(0)
    for value, mult in [
        (weeks, 604800),
        (days, 86400),
        (hours, 3600),
        (minutes, 60),
        (seconds, 1),
    ]:
        if value is not None:
            total += Decimal(value) * mult
    return _to_seconds(total)


def _parse_clock(text: str) -> int:
    fields = text.split(":")
    if len(fields) not in (2, 3):
        raise ValueError(f"invalid clock duration: {text!r}")
    for f in fields:
        if not _CLOCK_FIELD_RE.fullmatch(f):
            raise ValueError(f"invalid clock duration: {text!r}")
    # Only the last field may be fractional.
    for f in fields[:-1]:
        if "." in f:
            raise ValueError(f"invalid clock duration: {text!r}")
    values = [Decimal(f) for f in fields]
    if len(values) == 3:
        hours, minutes, seconds = values
    else:
        hours = Decimal(0)
        minutes, seconds = values
    if minutes >= 60 or seconds >= 60:
        raise ValueError(f"invalid clock duration: {text!r}")
    return _to_seconds(hours * 3600 + minutes * 60 + seconds)


def _parse_components(text: str) -> int:
    if not _FULL_COMPONENTS_RE.fullmatch(text):
        raise ValueError(f"invalid duration: {text!r}")
    total = Decimal(0)
    pos = 0
    while pos < len(text):
        m = _COMPONENT_RE.match(text, pos)
        if not m:
            raise ValueError(f"invalid duration: {text!r}")
        unit = m.group(2).lower()
        if unit not in _UNIT_SECONDS:
            raise ValueError(f"unknown unit {m.group(2)!r} in {text!r}")
        total += Decimal(m.group(1)) * _UNIT_SECONDS[unit]
        pos = m.end()
        while pos < len(text) and text[pos].isspace():
            pos += 1
    return _to_seconds(total)


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if not isinstance(text, str):
        raise ValueError("duration must be a string")
    s = text.strip()
    if not s:
        raise ValueError("empty duration")
    if s.startswith("-") or s.startswith("+"):
        raise ValueError(f"negative or signed duration not allowed: {text!r}")
    if _BARE_INT_RE.fullmatch(s):
        return int(s)
    if s[0] in "Pp":
        return _parse_iso(s.upper())
    if ":" in s:
        return _parse_clock(s)
    return _parse_components(s)

